using System;using System.IO;using System.IO.Compression;using System.Collections.Generic;using System.Drawing;using System.Drawing.Imaging;using System.Drawing.Drawing2D;using System.Text;using System.Globalization;
namespace EanEtikety {
public static class SceneOutput {
 public static string F(double v){return v.ToString("0.#####",CultureInfo.InvariantCulture);}
 static string Rect(RectangleF r){return "x=\""+F(r.X)+"\" y=\""+F(r.Y)+"\" width=\""+F(r.Width)+"\" height=\""+F(r.Height)+"\"";}
 public static string Svg(VectorScene scene,RectangleF view){var b=new StringBuilder("<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" width=\""+F(view.Width)+"mm\" height=\""+F(view.Height)+"mm\" viewBox=\""+F(view.X)+" "+F(view.Y)+" "+F(view.Width)+" "+F(view.Height)+"\"><defs><clipPath id=\"label\"><rect "+Rect(view)+"/></clipPath>");for(int i=0;i<scene.Shapes.Count;i++){b.Append("<clipPath id=\"c"+i+"\"><rect "+Rect(scene.Shapes[i].Clip)+"/></clipPath>");if(scene.Shapes[i].CanvasClip.HasValue)b.Append("<clipPath id=\"o"+i+"\"><rect "+Rect(scene.Shapes[i].CanvasClip.Value)+"/></clipPath>");}b.Append("</defs><g clip-path=\"url(#label)\">");for(int i=0;i<scene.Shapes.Count;i++){var sh=scene.Shapes[i];b.Append(sh.CanvasClip.HasValue?"<g clip-path=\"url(#o"+i+")\">":"<g>");b.Append("<g transform=\""+ElementTransform.Svg(sh)+"\" clip-path=\"url(#c"+i+")\">");if(sh.Bitmap!=null){using(var ms=new MemoryStream()){sh.Bitmap.Save(ms,ImageFormat.Png);b.Append("<image "+Rect(sh.ImageBounds)+" preserveAspectRatio=\"none\" xlink:href=\"data:image/png;base64,"+Convert.ToBase64String(ms.ToArray())+"\"/>");}}else if(sh.Path.PointCount>0)b.Append("<path fill=\"#"+sh.Fill.R.ToString("X2")+sh.Fill.G.ToString("X2")+sh.Fill.B.ToString("X2")+"\" fill-opacity=\""+F(sh.Fill.A/255d)+"\" fill-rule=\""+(sh.Path.FillMode==FillMode.Alternate?"evenodd":"nonzero")+"\" d=\""+VectorArt.PathData(sh.Path,true)+"\"/>");b.Append("</g></g>");}return b.Append("</g></svg>").ToString();}
 static byte[] Bytes(string s){return Encoding.ASCII.GetBytes(s);}
 static byte[] Stream(string dictionary,byte[] data){using(var m=new MemoryStream()){var head=Bytes("<< "+dictionary+" /Length "+data.Length+" >>\nstream\n");m.Write(head,0,head.Length);m.Write(data,0,data.Length);head=Bytes("\nendstream");m.Write(head,0,head.Length);return m.ToArray();}}
 static byte[] Deflate(byte[] data){using(var result=new MemoryStream()){result.WriteByte(0x78);result.WriteByte(0x9c);using(var z=new DeflateStream(result,CompressionLevel.Optimal,true))z.Write(data,0,data.Length);uint a=1,b=0;foreach(byte v in data){a=(a+v)%65521;b=(b+a)%65521;}uint checksum=(b<<16)|a;for(int n=24;n>=0;n-=8)result.WriteByte((byte)(checksum>>n));return result.ToArray();}}
 public static void Pdf(string path,OutputPlan plan){var objects=new List<byte[]>{null,null};var kids=new List<int>();for(int page=0;page<plan.PageCount;page++)using(var scene=plan.Scene(page)){
  int pageId=objects.Count+1;objects.Add(null);int contentId=objects.Count+1;objects.Add(null);kids.Add(pageId);var images=new StringBuilder();var alpha=new StringBuilder();var content=new StringBuilder("q "+F(72/25.4)+" 0 0 -"+F(72/25.4)+" 0 "+F(plan.Height*72/25.4)+" cm 0 0 "+F(plan.Width)+" "+F(plan.Height)+" re W n\n");int n=0;
  foreach(var shape in scene.Shapes){n++;content.Append("q\n");if(shape.CanvasClip.HasValue){var o=shape.CanvasClip.Value;content.Append(F(o.X)+" "+F(o.Y)+" "+F(o.Width)+" "+F(o.Height)+" re W n\n");}var c=shape.Clip;content.Append(ElementTransform.Pdf(shape)+F(c.X)+" "+F(c.Y)+" "+F(c.Width)+" "+F(c.Height)+" re W n\n");
   if(shape.Bitmap!=null){var bitmap=shape.Bitmap;var rgb=new byte[bitmap.Width*bitmap.Height*3];var mask=new byte[bitmap.Width*bitmap.Height];var locked=bitmap.LockBits(new Rectangle(0,0,bitmap.Width,bitmap.Height),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);try{var row=new byte[bitmap.Width*4];for(int y=0;y<bitmap.Height;y++){System.Runtime.InteropServices.Marshal.Copy(IntPtr.Add(locked.Scan0,y*locked.Stride),row,0,row.Length);for(int x=0;x<bitmap.Width;x++){int k=y*bitmap.Width+x;rgb[k*3]=row[x*4+2];rgb[k*3+1]=row[x*4+1];rgb[k*3+2]=row[x*4];mask[k]=row[x*4+3];}}}finally{bitmap.UnlockBits(locked);}int maskId=objects.Count+1;objects.Add(Stream("/Type /XObject /Subtype /Image /Width "+bitmap.Width+" /Height "+bitmap.Height+" /ColorSpace /DeviceGray /BitsPerComponent 8 /Filter /FlateDecode",Deflate(mask)));int imageId=objects.Count+1;objects.Add(Stream("/Type /XObject /Subtype /Image /Width "+bitmap.Width+" /Height "+bitmap.Height+" /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /FlateDecode /SMask "+maskId+" 0 R",Deflate(rgb)));images.Append("/I"+n+" "+imageId+" 0 R ");var r=shape.ImageBounds;content.Append(F(r.Width)+" 0 0 -"+F(r.Height)+" "+F(r.X)+" "+F(r.Bottom)+" cm /I"+n+" Do\n");}
   else if(shape.Path.PointCount>0){int alphaId=objects.Count+1;objects.Add(Bytes("<< /Type /ExtGState /ca "+F(shape.Fill.A/255d)+" >>"));alpha.Append("/A"+n+" "+alphaId+" 0 R ");content.Append("/A"+n+" gs "+F(shape.Fill.R/255d)+" "+F(shape.Fill.G/255d)+" "+F(shape.Fill.B/255d)+" rg\n"+VectorArt.PathData(shape.Path,false)+(shape.Path.FillMode==FillMode.Alternate?"f*":"f")+"\n");}content.Append("Q\n");
  }content.Append("Q\n");objects[pageId-1]=Bytes("<< /Type /Page /Parent 2 0 R /MediaBox [0 0 "+F(plan.Width*72/25.4)+" "+F(plan.Height*72/25.4)+"] /Resources << /XObject << "+images+" >> /ExtGState << "+alpha+" >> >> /Contents "+contentId+" 0 R >>");objects[contentId-1]=Stream("",Bytes(content.ToString()));
 }objects[0]=Bytes("<< /Type /Catalog /Pages 2 0 R >>");var children=new StringBuilder();foreach(int id in kids)children.Append(id+" 0 R ");objects[1]=Bytes("<< /Type /Pages /Count "+kids.Count+" /Kids ["+children+"] >>");using(var fs=File.Create(path)){Action<byte[]> write=bytes=>fs.Write(bytes,0,bytes.Length);write(Bytes("%PDF-1.4\n"));var offsets=new List<long>();for(int i=0;i<objects.Count;i++){offsets.Add(fs.Position);write(Bytes((i+1)+" 0 obj\n"));write(objects[i]);write(Bytes("\nendobj\n"));}long xref=fs.Position;write(Bytes("xref\n0 "+(objects.Count+1)+"\n0000000000 65535 f \n"));foreach(long offset in offsets)write(Bytes(offset.ToString("D10")+" 00000 n \n"));write(Bytes("trailer\n<< /Size "+(objects.Count+1)+" /Root 1 0 R >>\nstartxref\n"+xref+"\n%%EOF\n"));}}
}
public class OutputPlacement {public int Page;public LabelSettings Label;public RectangleF Bounds;}
public class OutputPlan {
 public DateTime? PreparedAt;public string VariableValues;public double Width,Height;public readonly List<OutputPlacement> Placements=new List<OutputPlacement>();public int PageCount{get{return Placements.Count==0?0:Placements[Placements.Count-1].Page+1;}}
 public static OutputPlan Create(LabelSettings label){return Create(new List<BatchRecord>{new BatchRecord{Label=label,Count=label.Layout.Enabled?label.Layout.Count:label.Copies}},label);}
 public static OutputPlan Create(List<BatchRecord> records,LabelSettings format,DateTime? preparedAt=null){var instant=preparedAt??(records.Count>0?records[0].PreparedAt:null)??DateTime.Now;var plan=new OutputPlan{PreparedAt=instant,Width=format.Layout.Enabled||format.UsePaper||format.Sheet?format.PageWidth:format.Width,Height=format.Layout.Enabled||format.UsePaper||format.Sheet?format.PageHeight:format.Height};bool sheet=format.Layout.Enabled;int cols=sheet?format.Layout.Columns:Engine.Columns(format),rows=sheet?format.Layout.Rows:Engine.Rows(format),slot=sheet?format.Layout.FirstSlot:0;double left=sheet?format.Layout.Left:format.UsePaper||format.Sheet?format.MarginX:0,top=sheet?format.Layout.Top:format.UsePaper||format.Sheet?format.MarginY:0,gapX=sheet?format.Layout.HorizontalGap:format.GapX,gapY=sheet?format.Layout.VerticalGap:format.GapY;
  if(double.IsNaN(left+top+gapX+gapY+format.Layout.Right+format.Layout.Bottom)||double.IsInfinity(left+top+gapX+gapY+format.Layout.Right+format.Layout.Bottom)||left<0||top<0||gapX<0||gapY<0||format.Layout.Right<0||format.Layout.Bottom<0)throw new InvalidDataException(Loc.T("Neplatné rozloženie hárka"));if(cols<1||rows<1||cols>100||rows>100||slot<0||slot>=cols*rows)throw new InvalidDataException(Loc.T("Neplatné rozloženie hárka"));if(sheet&&(left+cols*format.Width+(cols-1)*gapX+format.Layout.Right>plan.Width+.001||top+rows*format.Height+(rows-1)*gapY+format.Layout.Bottom>plan.Height+.001))throw new InvalidDataException(Loc.T("Etikety presahujú papier"));
  foreach(var record in records){if(record.Error!=null)throw new InvalidDataException(Loc.T("Dávka obsahuje chyby")+": "+record.Row+" — "+record.Error);if(record.Count<1||record.Count>10000)throw new InvalidDataException(Loc.T("Neplatný počet etikiet"));if(record.PreparedAt.HasValue&&record.PreparedAt.Value!=instant)throw new InvalidDataException(Loc.T("Záznamy majú odlišný čas prípravy. Pripravte dávku znova."));var frozen=JobPreparation.Resolve(record.Label,instant);if(!string.IsNullOrEmpty(record.VariableValues)){if(string.IsNullOrEmpty(plan.VariableValues))plan.VariableValues=record.VariableValues;else if(plan.VariableValues!=record.VariableValues)plan.VariableValues=records[0].VariableValues+" → "+record.VariableValues;}if(frozen.HideBarcode&&frozen.Symbols.Count==0&&!frozen.Texts.Exists(t=>!string.IsNullOrWhiteSpace(t.Text)))throw new InvalidDataException(Loc.T("Dokument neobsahuje nič na tlač."));for(int i=0;i<record.Count;i++,slot++){if(plan.Placements.Count>=10000)throw new InvalidDataException(Loc.T("Najviac 10000 etikiet"));int cell=slot%(cols*rows);plan.Placements.Add(new OutputPlacement{Page=slot/(cols*rows),Label=frozen,Bounds=new RectangleF((float)(left+cell%cols*(format.Width+gapX)),(float)(top+cell/cols*(format.Height+gapY)),(float)format.Width,(float)format.Height)});}}if(plan.Placements.Count==0)throw new InvalidDataException(Loc.T("Dokument neobsahuje nič na tlač."));return plan;
 }
 public VectorScene Scene(int page){if(page<0||page>=PageCount)throw new ArgumentOutOfRangeException();var scene=new VectorScene{Width=Width,Height=Height};try{int element=0;foreach(var p in Placements)if(p.Page==page)using(var source=VectorArt.Build(p.Label)){var indices=new Dictionary<int,int>();foreach(var shape in source.Shapes){int key;if(!indices.TryGetValue(shape.Element,out key)){key=element++;indices.Add(shape.Element,key);}var copy=shape.Copy();using(var m=new Matrix()){m.Translate(p.Bounds.X,p.Bounds.Y);copy.Path.Transform(m);}copy.Pivot=new PointF(copy.Pivot.X+p.Bounds.X,copy.Pivot.Y+p.Bounds.Y);var clip=copy.Clip;clip.Offset(p.Bounds.X,p.Bounds.Y);copy.Clip=clip;var image=copy.ImageBounds;image.Offset(p.Bounds.X,p.Bounds.Y);copy.ImageBounds=image;copy.CanvasClip=p.Bounds;copy.Element=key;scene.Shapes.Add(copy);}}return scene;}catch{scene.Dispose();throw;}}
}
}
